import toast from "react-hot-toast"
import { useFavorites } from "../store"

export default function Otherdrinks() {
  const Date = [
    { Name: "Cappuccino", Description: "Enjoy a rich experience with authentic Italian cappuccino", Price: 60, img: 'data:image/jpeg;base64,' },
    { Name: "Spanish latte", Description: "Rich espresso creamy steamed milk and a sweet hint of milk", Price: 65, img: 'data:image/jpeg;base64,' },
    { Name: "Nescafe", Description: "Covered with a thick layer of velvety foam An ideal choice for black coffee lovers", Price: 45, img: 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcR8CkjWutcPgIQO3Lw85qaVhH2Uf33ThMS-chdnsWy8lQ&s' },
    { Name: "Hot chocolate", Description: "A rich blend of premium cocoa and evaporated milk", Price: 60, img: 'data:image/jpeg;base64,' },
    { Name: "Oreo Hot Chocolate", Description: "The finest cocoa and whole milk mixed with Oreo cookie pieces", Price: 70, img: 'data:image/jpeg;base64,' },
    { Name: "White Hot Chocolate", Description: "A creamy and warm blend of luxurious white chocolate and warm milk", Price: 75, img: 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcQH78NfMTySg8f_F8O_rn8aPbX8kyXsueTcZg&s' },
    { Name: "Nutella hot chocolate", Description: "Enjoy the warmth of winter with a rich and velvety mug of Nutella hot chocolate", Price: 73, img: 'data:image/jpeg;base64,' },
    { Name: "Mocha", Description: "A rich blend of hot espresso coffee with luxurious dark chocolate and steamed milk", Price: 75, img: 'data:image/jpeg;base64,' },
    { Name: "Mocha latte", Description: "Espresso rich chocolate and creamy milk", Price: 80, img: 'data:image/jpeg;base64,' },
    { Name: "Mocha Nutella", Description: "Mocha The allure of hazelnut chocolate with creamy espresso", Price: 80, img: 'data:image/jpeg;base64,' },
    { Name: "Sahlab", Description: "Enjoy the warmth of winter with a cup of authentic Turkish salep prepared", Price: 70, img: 'data:image/jpeg;base64,' },
    { Name: "Sahlab fruits", Description: "Enjoy the warmth of winter with a cup of authentic Turkish salep prepared with fruit  ", Price: 85, img: 'data:image/jpeg;base64,' },
  ]
  const { favorites, setFavorites } = useFavorites()
  const addel = (el) => {
    let date = favorites.findIndex((pro) => pro.Name == el.Name)
    let copy = [...favorites]
    if (date == -1) {
      copy.push({ ...el, qty: 1 })
      toast.success("add is order with favorites")
    }
    setFavorites(copy)
    sessionStorage.setItem('order', JSON.stringify(copy))
  }

  return (
    <div>
      <div className='flex flex-col '>
        <p className="font-bold text-[26px] md:text-[36px] underline  p-2 md:pt-6 md:px-10"> Other drinks </p>
        <div className="flex items-center justify-center w-full  ">
          <div className="carousel  rounded-2xl carousel-center  h-93 md:h-95  max-w-xs md:min-w-[82%]" >
            <div className=" grid  grid-cols-2 md:grid-cols-5  gap-2 md:gap-4 ">

              {Date.map((el, index) => {
                return (
                  <div key={index} className='w-39 md:w-55 h-auto gap-2  bg-emerald-50 rounded-2xl p-2 flex flex-col justify-between shrink-0'>
                    <img className='rounded-2xl  object-fill w-full h-37 ' src={el.img} alt="" />
                    <div className='flex flex-col  gap-1 h-19 md:h-22'>
                      <h1 className='underline text-[12px] md:text-[18px]'>{el.Name}</h1>
                      <p className='text-[11px] md:text-[14px] text-gray-400'>{el.Description}</p>
                    </div>
                    <div className="flex  items-center justify-between ">
                      <p className='text-[16px]' >{el.Price} EGP</p>

                      <button
                        onClick={() => addel(el)}
                        title="Add New"
                        className="group cursor-pointer outline-none hover:rotate-90 duration-300 "
                      >

                        <svg
                          xmlns="http://www.w3.org/2000/svg"
                          width="50px"
                          height="50px"
                          viewBox="0 0 24 24"
                          className="stroke-zinc-400 fill-none w-10 h-10 md:w-auto md:h-auto group-hover:fill-zinc-800 group-active:stroke-zinc-200 group-active:fill-zinc-600 group-active:duration-0 duration-300"
                        >
                          <path
                            d="M12 22C17.5 22 22 17.5 22 12C22 6.5 17.5 2 12 2C6.5 2 2 6.5 2 12C2 17.5 6.5 22 12 22Z"
                          ></path>
                          <path d="M8 12H16" strokeWidth="1.5"></path>
                          <path d="M12 16V8" strokeWidth="1.5"></path>
                        </svg>
                      </button>
                    </div>
                  </div>
                )
              })}
            </div>
          </div>
        </div>
      </div>

    </div>
  )
}
